import * as THREE from 'three';
import { fbm, smoothstep, mulberry32, valueNoise } from './Placement.js';

/**
 * The shape of the world: a city on flat ground at the origin with three biome
 * regions arranged around it.
 *
 * Terrain is a single analytic heightfield rather than a mesh, so gameplay
 * code can ask for the ground height anywhere (placing buildings, spawning
 * monsters, sitting the camera on slopes) without a raycast. The ground mesh
 * is generated by sampling the same function, which guarantees they agree.
 */

export const CITY = {
  id: 'city',
  name: 'Ravenshold',
  radius: 42,       // flat, buildable ground
  wallRadius: 45,   // where the curtain wall stands
  gateAngle: 0,     // facing +Z
  gateWidth: 7,
};

/** Mission zones, evenly spaced around the city. */
export const REGIONS = [
  {
    id: 'forest',
    name: 'Wildwood',
    biome: 'forest',
    blurb: 'Old greenwood. Wolves and worse den under the canopy.',
    center: [0, -168],
    radius: 92,
    fog: 0xc8d4c0,
    sky: [0x3f6a93, 0xf2d3a2],
  },
  {
    id: 'blight',
    name: 'Emberwood',
    biome: 'blight',
    blurb: 'Something burnt here and never stopped burning.',
    center: [146, 84],
    radius: 92,
    fog: 0xb08a6a,
    sky: [0x4a3a52, 0xdba072],
  },
  {
    id: 'desert',
    name: 'Sunscorch Flats',
    biome: 'desert',
    blurb: 'Bone-dry mesas. The heat alone has killed better rangers.',
    center: [-146, 84],
    radius: 92,
    fog: 0xe4cfa0,
    sky: [0x5b83a8, 0xf6e2b4],
  },
];

export const GRASSLAND = {
  id: 'grassland',
  name: 'Kingsroad',
  biome: 'grassland',
  blurb: 'Open ground between the walls and the wild.',
};

export function regionById(id) {
  return REGIONS.find((r) => r.id === id) || null;
}

// ------------------------------------------------------------------ height

function baseHeight(x, z) {
  return (fbm(x * 0.0055, z * 0.0055, 7, 3) - 0.5) * 5.5;
}

function biomeHeight(biome, x, z) {
  switch (biome) {
    case 'forest':
      // soft, walkable hills under the canopy
      return (fbm(x * 0.010, z * 0.010, 21, 3) - 0.5) * 10;

    case 'blight': {
      // ridged noise gives the twisted, gully-ridden ground
      const ridge = 1 - Math.abs(fbm(x * 0.015, z * 0.015, 31, 3) * 2 - 1);
      return (fbm(x * 0.013, z * 0.013, 33, 3) - 0.5) * 11 + ridge * ridge * 5;
    }

    case 'desert': {
      // long dunes, plus flat-topped mesas where the noise crosses a threshold
      const dunes = Math.sin(x * 0.055 + fbm(x * 0.006, z * 0.006, 41, 2) * 9) * 2.2
                  + Math.sin(z * 0.041 + fbm(x * 0.007, z * 0.007, 47, 2) * 7) * 1.8;
      const mesa = smoothstep(0.60, 0.655, fbm(x * 0.0065, z * 0.0065, 43, 2)) * 15;
      return dunes + mesa;
    }

    default:
      return 0;
  }
}

/** Biome blend weights at a point, normalised. */
export function biomeWeights(x, z) {
  const out = [];
  let sum = 0;
  for (const r of REGIONS) {
    const d = Math.hypot(x - r.center[0], z - r.center[1]);
    const w = 1 - smoothstep(r.radius * 0.42, r.radius * 1.18, d);
    if (w <= 0.002) continue;
    out.push([r, w]);
    sum += w;
  }
  if (sum <= 0) return [];
  return out.map(([r, w]) => [r, w / sum]);
}

/** Ground height anywhere in the world. */
export function terrainHeight(x, z) {
  let h = baseHeight(x, z);

  const weights = biomeWeights(x, z);
  if (weights.length) {
    let blended = 0;
    for (const [r, w] of weights) blended += biomeHeight(r.biome, x, z) * w;
    h = THREE.MathUtils.lerp(h, blended, Math.min(1, weights.reduce((s, [, w]) => s + w, 0)));
  }

  // the city sits on levelled ground so buildings do not tilt
  const dc = Math.hypot(x, z);
  const flat = 1 - smoothstep(CITY.radius + 2, CITY.radius + 30, dc);
  return THREE.MathUtils.lerp(h, 0, flat);
}

/** Slope steepness, used to keep buildings and props off cliffs. */
export function terrainSlope(x, z, step = 1.5) {
  const dx = terrainHeight(x + step, z) - terrainHeight(x - step, z);
  const dz = terrainHeight(x, z + step) - terrainHeight(x, z - step);
  return Math.hypot(dx, dz) / (2 * step);
}

/** Which region a point falls inside, or null for open grassland. */
export function regionAt(x, z) {
  for (const r of REGIONS) {
    if (Math.hypot(x - r.center[0], z - r.center[1]) <= r.radius) return r;
  }
  if (Math.hypot(x, z) <= CITY.wallRadius) return CITY;
  return null;
}

/** Dominant biome id at a point ('grassland' between regions). */
export function biomeAt(x, z) {
  const weights = biomeWeights(x, z);
  if (!weights.length) return 'grassland';
  return weights.reduce((a, b) => (b[1] > a[1] ? b : a))[0].biome;
}

// ------------------------------------------------------------------ ground

const GROUND_COLOURS = {
  grassland: [0x7d8a55, 0x9aa763, 0xb8c17c],
  forest: [0x5e7340, 0x76914d, 0x93a962],
  blight: [0x5a4630, 0x74563a, 0x8f6a44],
  desert: [0xbfa367, 0xd8bd7e, 0xe8d5a0],
};

function groundTexture(rng) {
  const size = 512;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#8a9560';
  ctx.fillRect(0, 0, size, size);

  const blob = (x, y, r, style) => {
    for (const ox of [-size, 0, size]) {
      for (const oy of [-size, 0, size]) {
        ctx.beginPath();
        ctx.arc(x + ox, y + oy, r, 0, Math.PI * 2);
        ctx.fillStyle = style;
        ctx.fill();
      }
    }
  };
  for (let i = 0; i < 1400; i++) {
    blob(rng() * size, rng() * size, 4 + rng() * 26,
      `hsla(${58 + rng() * 50}, ${18 + rng() * 24}%, ${26 + rng() * 24}%, ${0.09 + rng() * 0.2})`);
  }

  const img = ctx.getImageData(0, 0, size, size);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rng() - 0.5) * 26;
    d[i] += n; d[i + 1] += n; d[i + 2] += n;
  }
  ctx.putImageData(img, 0, 0);

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(90, 90);
  tex.anisotropy = 8;
  return tex;
}

/** One mesh for the whole world, coloured per biome from the same weights. */
export function buildGround(seed = 99) {
  const rng = mulberry32(seed);
  const size = 660;
  const segs = 200;

  const geo = new THREE.PlaneGeometry(size, size, segs, segs);
  geo.rotateX(-Math.PI / 2);

  const pos = geo.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const tmp = new THREE.Color();
  const dark = new THREE.Color();
  const mid = new THREE.Color();
  const light = new THREE.Color();

  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const z = pos.getZ(i);
    pos.setY(i, terrainHeight(x, z));

    const weights = biomeWeights(x, z);
    const palette = weights.length
      ? GROUND_COLOURS[weights.reduce((a, b) => (b[1] > a[1] ? b : a))[0].biome]
      : GROUND_COLOURS.grassland;
    dark.setHex(palette[0]);
    mid.setHex(palette[1]);
    light.setHex(palette[2]);

    const n = valueNoise(x * 0.09, z * 0.09, 3) * 0.6 + valueNoise(x * 0.4, z * 0.4, 11) * 0.4;
    tmp.copy(dark).lerp(mid, THREE.MathUtils.clamp(n * 1.5, 0, 1));
    tmp.lerp(light, THREE.MathUtils.clamp((n - 0.55) * 1.6, 0, 1));
    colors[i * 3] = tmp.r;
    colors[i * 3 + 1] = tmp.g;
    colors[i * 3 + 2] = tmp.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geo.computeVertexNormals();

  const mat = new THREE.MeshStandardMaterial({
    map: groundTexture(rng),
    vertexColors: true,
    roughness: 0.98,
    metalness: 0,
  });

  const mesh = new THREE.Mesh(geo, mat);
  mesh.receiveShadow = true;
  mesh.name = 'ground';
  return mesh;
}
